74	  /**
75	   * Returns the API key from config file or PROMPTFOO_API_KEY environment variable.
76	   * Config file takes precedence over environment variable.
77	   */
78	  private resolveApiKey(): string | undefined {
79	    return this.config.apiKey || process.env.PROMPTFOO_API_KEY;
