46	/**
47	 * Fetches a provider configuration from PromptFoo Cloud by its ID.
48	 * @param id - The unique identifier of the cloud provider
49	 * @returns Promise resolving to provider options with guaranteed id field
50	 * @throws Error if cloud is not enabled, provider not found, or request fails
51	 */
52	export async function getProviderFromCloud(id: string): Promise<ProviderOptions & { id: string }> {
53	  if (!cloudConfig.isEnabled()) {
54	    throw new Error(
55	      `Could not fetch Provider ${id} from cloud. Cloud config is not enabled. Please run \`promptfoo auth login\` to login.`,
56	    );
57	  }
58	  try {
59	    const response = await makeRequest(`providers/${id}`, 'GET');
60	
61	    if (!response.ok) {
62	      const errorMessage = await response.text();
63	      logger.error(
64	        `[Cloud] Failed to fetch provider from cloud: ${errorMessage}. HTTP Status: ${response.status} -- ${response.statusText}.`,
65	      );
66	      throw new Error(`Failed to fetch provider from cloud: ${response.statusText}`);
67	    }
68	    const body = await response.json();
69	    logger.debug(`Provider fetched from cloud: ${id}`);
70	
71	    const provider = ProviderOptionsSchema.parse(body.config);
72	    // The provider options schema has ID field as optional but we know it's required for cloud providers
73	    invariant(provider.id, `Provider ${id} has no id in ${body.config}`);
74	    return { ...provider, id: provider.id };
75	  } catch (e) {
76	    logger.error(`Failed to fetch provider from cloud: ${id}.`);
77	    logger.error(String(e));
78	
79	    throw new Error(`Failed to fetch provider from cloud: ${id}.`);
80	  }
81	}
