32	      '-t, --team <team>',
33	      'The team to use (name, slug, or ID). Required in CI when multiple teams exist.',
34	    )
35	    .action(async (cmdObj: { orgId: string; host: string; apiKey: string; team?: string }) => {
36	      let token: string | undefined;
37	      const apiHost = cmdObj.host || cloudConfig.getApiHost();
38	
39	      try {
40	        if (cmdObj.apiKey) {
41	          token = cmdObj.apiKey;
42	          const { user, organization } = await cloudConfig.validateAndSetApiToken(token, apiHost);
43	          // Store token in global config and handle email sync
44	          const existingEmail = getUserEmail();
45	          if (existingEmail && existingEmail !== user.email) {
46	            logger.info(
47	              chalk.yellow(
48	                `Updating local email configuration from ${existingEmail} to ${user.email}`,
49	              ),
50	            );
51	          }
52	          setUserEmail(user.email);
53	
54	          // Set current organization context
55	          cloudConfig.setCurrentOrganization(organization.id);
56	
57	          // Display login success with user/org info
58	          logger.info(chalk.green.bold('Successfully logged in'));
59	          logger.info(`User: ${chalk.cyan(user.email)}`);
60	          logger.info(`Organization: ${chalk.cyan(organization.name)}`);
61	          logger.info(`App: ${chalk.cyan(cloudConfig.getAppUrl())}`);
62	
63	          // Set up team
64	          try {
65	            const allTeams = await getUserTeams();
66	            cloudConfig.cacheTeams(allTeams, organization.id);
67	
68	            let selectedTeam;
69	
70	            if (cmdObj.team) {
71	              // --team flag provided: use specified team
72	              selectedTeam = await resolveTeamFromIdentifier(cmdObj.team);
73	              cloudConfig.setCurrentTeamId(selectedTeam.id, organization.id);
74	              logger.info(`Team: ${chalk.cyan(selectedTeam.name)}`);
75	            } else if (allTeams.length === 1) {
76	              // Single team: just use it
77	              selectedTeam = allTeams[0];
