}

/**
 * Returns the team with the earliest createdAt date (the oldest team).
 */
function pickOldestTeam(teams: UserTeam[]): UserTeam {
  return [...teams].sort(
    (a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime(),
  )[0];
}

/**
