async function selectTeamFromSet(teams: UserTeam[], organizationId: string): Promise<void> {
  if (teams.length === 0) {
    return;
  }

  if (teams.length === 1) {
    cloudConfig.setCurrentTeamId(teams[0].id, organizationId);
    logger.info(`Team: ${chalk.cyan(teams[0].name)}`);
