/**
 * Resolves the organization and team context for login based on the provided flags,
 * persisting the organization/team selection (but not credentials).
 * @returns `true` when resolution succeeded; `false` when the requested organization has
 *   no accessible teams (in which case an error has already been logged and
 *   `process.exitCode` set). Throws for other resolution failures.
 */
async function resolveLoginOrgAndTeam(
  cmdObj: { org?: string; team?: string },
  allTeams: UserTeam[],
  fallbackOrganizationId: string,
): Promise<boolean> {
  if (cmdObj.team && !cmdObj.org) {
    // --team without --org: search for the team across all organizations.
    const found = findTeamByIdentifier(allTeams, cmdObj.team);
    if (!found) {
      const availableTeams = allTeams.map((t) => t.name).join(', ');
      throw new Error(`Team '${cmdObj.team}' not found. Available teams: ${availableTeams}`);
    }
    const orgTeams = allTeams.filter((t) => t.organizationId === found.organizationId);
    cloudConfig.setCurrentOrganization(found.organizationId);
    cloudConfig.cacheTeams(orgTeams, found.organizationId);
    cloudConfig.setCurrentTeamId(found.id, found.organizationId);
    logger.info(`Team: ${chalk.cyan(found.name)}`);
    return true;
  }

  if (cmdObj.org) {
    // --org specified: restrict resolution to teams in that organization.
    const orgId = cmdObj.org;
    const orgTeams = allTeams.filter((t) => t.organizationId === orgId);
    if (orgTeams.length === 0) {
      const availableOrgIds = [
        ...new Set([fallbackOrganizationId, ...allTeams.map((t) => t.organizationId)]),
      ].join(', ');
      logger.error(
        `Authentication failed: Organization '${orgId}' not found in your accessible teams. Available organizations: ${availableOrgIds}`,
      );
      process.exitCode = 1;
      return false;
    }
    cloudConfig.setCurrentOrganization(orgId);
    cloudConfig.cacheTeams(orgTeams, orgId);

    if (cmdObj.team) {
      const found = findTeamByIdentifier(orgTeams, cmdObj.team);
      if (!found) {
        const availableTeams = orgTeams.map((t) => t.name).join(', ');
        throw new Error(
          `Team '${cmdObj.team}' not found in organization '${orgId}'. Available teams: ${availableTeams}`,
        );
      }
      cloudConfig.setCurrentTeamId(found.id, orgId);
      logger.info(`Team: ${chalk.cyan(found.name)}`);
    } else {
      await selectTeamFromSet(orgTeams, orgId);
    }
    return true;
  }

  // No flags: use the default organization from the token validation response.
  let resolvedOrgId = fallbackOrganizationId;
  let orgTeams = allTeams.filter((t) => t.organizationId === resolvedOrgId);

  if (orgTeams.length === 0 && allTeams.length > 0) {
    // The default organization has no accessible teams but others do: resolve to the
    // organization containing the oldest-created team.
    const oldest = pickOldestTeam(allTeams);
    resolvedOrgId = oldest.organizationId;
    orgTeams = allTeams.filter((t) => t.organizationId === resolvedOrgId);
    cloudConfig.setCurrentOrganization(resolvedOrgId);
    cloudConfig.cacheTeams(orgTeams, resolvedOrgId);
    logger.info(`Organization: ${resolvedOrgId}`);
  } else {
    cloudConfig.setCurrentOrganization(resolvedOrgId);
    cloudConfig.cacheTeams(orgTeams, resolvedOrgId);
  }

